// src/commands/plugin-state.ts
init_paths();
import { readFileSync as readFileSync5 } from "fs";
import { join as join3 } from "path";
var PLUGIN_NAME = "claude-telegram";
var MARKETPLACE = "flxxxxddd/claude-telegram";
function pluginInstalled() {
  try {
    const raw = readFileSync5(join3(claudeHome(), "plugins", "installed_plugins.json"), "utf8");
    const parsed = JSON.parse(raw);
    return Object.keys(parsed.plugins ?? {}).some((key) => key.split("@")[0] === PLUGIN_NAME);
  } catch {
    return false;
  }
}
var INSTALL_STEPS = [
  `claude plugin marketplace add ${MARKETPLACE}`,
  `claude plugin install ${PLUGIN_NAME}@${PLUGIN_NAME}`
];

// src/commands/settings-file.ts
init_paths();
import { existsSync as existsSync7, mkdirSync as mkdirSync6, readFileSync as readFileSync6, writeFileSync as writeFileSync4 } from "fs";
import { dirname as dirname2, join as join4 } from "path";
var HOOK_EVENTS = ["UserPromptSubmit", "PostToolUse", "Stop", "SessionEnd"];
function settingsPath() {
  return join4(claudeHome(), "settings.json");
}
function readSettings() {
  try {
    const raw = JSON.parse(readFileSync6(settingsPath(), "utf8"));
    return raw && typeof raw === "object" ? raw : {};
  } catch {
    return {};
  }
}
function hooksInstalled(command2) {
  const hooks = readSettings().hooks ?? {};
  return HOOK_EVENTS.every((event) => (hooks[event] ?? []).some((matcher) => (matcher.hooks ?? []).some((hook) => hook.command === command2)));
}
function installHooks(command2) {
  const settings2 = readSettings();
  const hooks = { ...settings2.hooks ?? {} };
  const added = [];
  for (const event of HOOK_EVENTS) {
    const matchers = [...hooks[event] ?? []];
    const present = matchers.some((m) => (m.hooks ?? []).some((h) => h.command === command2));
    if (present)
      continue;
    matchers.push(event === "PostToolUse" ? { matcher: "*", hooks: [{ type: "command", command: command2 }] } : { hooks: [{ type: "command", command: command2 }] });
    hooks[event] = matchers;
    added.push(event);
  }
  if (added.length) {
    const path = settingsPath();
    mkdirSync6(dirname2(path), { recursive: true });
    if (existsSync7(path))
      writeFileSync4(`${path}.cctg-backup`, readFileSync6(path));
    writeFileSync4(path, `${JSON.stringify({ ...settings2, hooks }, null, 2)}
`);
  }
  return { added, path: settingsPath() };
}
function removeHooks(command2) {
  const settings2 = readSettings();
  const hooks = { ...settings2.hooks ?? {} };
  const removed = [];
  for (const event of HOOK_EVENTS) {
    const matchers = hooks[event];
    if (!matchers)
      continue;
    const kept = matchers.map((m) => ({ ...m, hooks: (m.hooks ?? []).filter((h) => h.command !== command2) })).filter((m) => (m.hooks ?? []).length > 0);
    if (kept.length !== matchers.length)
      removed.push(event);
    if (kept.length)
      hooks[event] = kept;
    else
      delete hooks[event];
  }
  if (removed.length)
    writeFileSync4(settingsPath(), `${JSON.stringify({ ...settings2, hooks }, null, 2)}
`);
  return removed;
}

// src/commands/setup.ts
function hookCommand() {
  if (spawnSync("command", ["-v", "cctg"], { shell: true }).status === 0)
    return "cctg hook";
  const { exec, script } = selfEntry();
  return `${exec} ${script} hook`;
}
var CHANNEL_FLAG2 = "claude --channels plugin:claude-telegram@claude-telegram";
async function setup(args) {
  const hooksOnly = args.includes("--hooks");
  const rl = createInterface({ input: process.stdin, output: process.stdout });
  const ask2 = async (question) => (await rl.question(question)).trim();
  try {
    console.log(heading("cctg setup"));
    if (!hooksOnly) {
      const existing = botToken();
      if (existing) {
        console.log(ok(`a token is already stored (${existing.split(":")[0]})`));
      } else {
        console.log(info("Create a bot: open @BotFather, send /newbot, and copy the token it replies with."));
        const token = await ask2(`${cyan("token")} > `);
        if (!looksLikeToken(token)) {
          console.log(bad("that is not shaped like a Telegram token (<bot id>:<secret>)"));
          return 1;
        }
        saveBotToken(token);
        console.log(ok(`saved to ${paths.env}`));
      }
      console.log(info("Topic Mode gives every project its own thread inside your DM with the bot."));
      console.log(info("Turn it on in @BotFather: Bot Settings \u2192 Topic Mode \u2192 Enable."));
      const locale = await ask2(`${cyan("interface language")} [en/ru] > `);
      if (locale === "ru" || locale === "en") {
        saveConfig({ locale });
        console.log(ok(`interface language set to ${locale}`));
      }
    }
    const command2 = hookCommand();
    if (pluginInstalled()) {
      console.log(ok("mirror hooks come from the plugin"));
      const removed = removeHooks(command2);
      if (removed.length)
        console.log(ok(`removed the duplicate copy in ${settingsPath()}`));
    } else if (hooksInstalled(command2)) {
      console.log(ok("mirror hooks already wired"));
    } else {
      console.log(info(`The mirror needs ${HOOK_EVENTS.length} hooks in ${settingsPath()}.`));
      console.log(dim(`  ${command2}`));
      const answer = await ask2(`${cyan("add them now?")} [Y/n] > `);
      if (answer.toLowerCase().startsWith("n")) {
        console.log(warn("skipped \u2014 the pinned status and turn mirror stay off until they are wired"));
      } else {
        const { added, path } = installHooks(command2);
        console.log(ok(`added ${added.join(", ")} to ${path}`));
      }
    }
    const config = loadConfig();
    const access = loadAccess();
    const live = await askStatus();
    const installed2 = pluginInstalled();
    console.log(heading("next"));
    if (!installed2) {
      console.log(warn("the plugin is not installed \u2014 the channel flag does nothing without it"));
      for (const step of INSTALL_STEPS)
        console.log(`     ${bold(step)}`);
    }
    if (!live)
      console.log(`  ${ok("")}${bold("cctg daemon start")}   ${dim("(or just open a Claude Code session)")}`);
    console.log(`  Start a session with ${bold(CHANNEL_FLAG2)}`);
    if (!access.allowedUsers.length) {
      console.log(`  DM your bot; it replies with a code. Run ${bold("/cctg:access pair <code>")} in the session.`);
      console.log(`  Once you are in, ${bold("/cctg:access policy allowlist")} so strangers get nothing.`);
    }
    if (!config.launchCmd) {
      console.log(`
${info("To start sessions from Telegram, set TELEGRAM_LAUNCH_CMD, e.g.")}`);
      console.log(dim(`  export TELEGRAM_LAUNCH_CMD="tmux new-session -d -s cctg_{name} -c {cwd} '{claude}'"`));
    }
    return 0;
  } finally {
    rl.close();
  }
}

// src/commands/doctor.ts
var render2 = (check) => {
  const line = check.level === "ok" ? ok(check.text) : check.level === "warn" ? warn(check.text) : bad(check.text);
  return check.fix ? `${line}
    ${dim(check.fix)}` : line;
};
async function doctor() {
  const checks = [];
  const config = loadConfig();
  const token = botToken();
  if (!token) {
    checks.push({ level: "bad", text: "no bot token", fix: "run `cctg setup`" });
  } else if (!looksLikeToken(token)) {
    checks.push({
      level: "bad",
      text: "the stored token is not shaped like a Telegram token",
      fix: `expected <bot id>:<secret>; check ${paths.env}`
    });
  } else {
    checks.push({ level: "ok", text: `token present (${token.split(":")[0]})` });
  }
  const live = await askStatus();
  if (live) {
    checks.push({ level: "ok", text: `daemon ${live.version} running as @${live.botUsername} (pid ${live.pid})` });
    checks.push(live.topicsEnabled ? { level: "ok", text: "topic mode is on \u2014 every project gets its own thread" } : {
      level: "warn",
      text: "topic mode is off, so every chat carries one session at a time",
      fix: "in @BotFather: Bot Settings \u2192 Topic Mode \u2192 Enable, then `cctg daemon restart`"
    });
    checks.push({
      level: live.sessions.length ? "ok" : "warn",
      text: `${live.sessions.length} session(s) connected`,
      fix: live.sessions.length ? undefined : "start Claude Code with `--channels plugin:claude-telegram@claude-telegram`"
    });
  } else {
    checks.push({
      level: "warn",
      text: "no daemon is running",
      fix: "run `cctg daemon start`, or open a Claude Code session \u2014 the first one starts it"
    });
  }
  const access = loadAccess();
  if (!access.allowedUsers.length && !access.allowedChats.length) {
    checks.push({
      level: "warn",
      text: "nobody is allowed yet",
      fix: "DM the bot, then run `/cctg:access pair <code>` in your session"
    });
  } else {
    checks.push({
      level: "ok",
      text: `${access.allowedUsers.length} user(s), ${access.allowedChats.length} chat(s) allowed \xB7 policy ${access.dmPolicy}`
    });
    if (access.dmPolicy === "pairing") {
      checks.push({
        level: "warn",
        text: "policy is still `pairing`, so strangers get a pairing code",
        fix: "run `/cctg:access policy allowlist` once you are in"
      });
    }
  }
  checks.push(pluginInstalled() ? { level: "ok", text: "the plugin is installed" } : {
    level: "bad",
    text: "the plugin is not installed, so the channel flag resolves to nothing",
    fix: INSTALL_STEPS.join("  &&  ")
  });
  const command2 = hookCommand();
  const wiredByHand = hooksInstalled(command2);
  if (pluginInstalled()) {
    checks.push(wiredByHand ? {
      level: "bad",
      text: "the mirror hooks are wired twice \u2014 once by the plugin, once in settings.json",
      fix: `run \`cctg setup --hooks\` to drop the copy in ${settingsPath()}; duplicates deliver every` + " event twice, and a second Stop cancels the message the first one is sending"
    } : { level: "ok", text: "mirror hooks come from the plugin" });
  } else {
    checks.push(wiredByHand ? { level: "ok", text: "mirror hooks are wired" } : {
      level: config.mirror === "off" ? "ok" : "warn",
      text: config.mirror === "off" ? "mirroring is off by configuration" : "mirror hooks are not wired",
      fix: config.mirror === "off" ? undefined : `run \`cctg setup --hooks\` to add them to ${settingsPath()}`
    });
  }
  checks.push(existsSync8(paths.db) ? { level: "ok", text: `state database at ${paths.db} (${topics.all(db()).length} topics)` } : { level: "warn", text: "no state database yet \u2014 it is created on first run" });
  console.log(heading("cctg doctor"));
  for (const check of checks)
    console.log(render2(check));
  console.log(`
${info(`state directory: ${paths.state}`)}`);
  return checks.some((c) => c.level === "bad") ? 1 : 0;
}

// src/commands/status.ts
init_db();
init_paths();
init_repos();
async function status() {
  const live = await askStatus();
  if (!live) {
    console.log(bad("no daemon is running"));
    console.log(info(`start one with \`cctg daemon start\`, or open a Claude Code session \u2014 the first one starts it`));
    return 1;
  }
  console.log(heading(`daemon ${live.version}`));
  console.log(pairs([
    ["bot", `@${live.botUsername}`],
    ["pid", String(live.pid)],
    ["uptime", ago(live.startedAt).replace(" ago", "")],
    ["threading", live.threadMode === "topics" ? ok("topics") : dim("flat (topic mode is off in BotFather)")],
    ["state", paths.state]
  ]));
  console.log(heading(`sessions (${live.sessions.length})`));
  if (!live.sessions.length) {
    console.log(info("none connected"));
  } else {
    for (const session2 of live.sessions) {
      const marks = [session2.busy ? cyan("working") : dim("idle")];
      if (session2.launched)
        marks.push(dim("launched from telegram"));
      console.log(`  ${bold(session2.title)}  ${marks.join(" \xB7 ")}`);
      console.log(pairs([
        ["project", projectName(session2.cwd)],
        ["path", dim(session2.cwd)],
        ["model", session2.model ?? dim("not reported yet")],
        ["topic", session2.threadId ? String(session2.threadId) : dim("none")],
        ["connected", ago(session2.connectedAt)]
      ]));
    }
  }
  const conn = db();
  const known = topics.all(conn);
  if (known.length) {
    console.log(heading(`topics (${known.length})`));
    for (const topic of known) {
      const held = queue.depth(conn, topic.cwd);
      console.log(`  ${bold(topic.name)}  ${dim(topic.cwd)}${held ? cyan(`  ${held} queued`) : ""}`);
    }
  }
  return 0;
}

// src/cli.ts
var USAGE = `${heading(`cctg ${VERSION}`)}
Drive Claude Code from Telegram.

  ${bold("cctg setup")}              first run: token, language, mirror hooks
  ${bold("cctg setup --hooks")}      only wire the mirror hooks
  ${bold("cctg status")}             connected sessions, topics and queues
  ${bold("cctg doctor")}             check every link in the chain
  ${bold("cctg daemon start")}       run the bridge in this terminal
  ${bold("cctg daemon start --detach")}
  ${bold("cctg daemon stop")}
  ${bold("cctg daemon restart")}
  ${bold("cctg daemon log -f")}      follow the daemon log
  ${bold("cctg hook")}               internal: a Claude Code hook event on stdin
  ${bold("cctg mcp")}                internal: the per-session MCP shim

${dim("State lives in $TELEGRAM_STATE_DIR, or ~/.claude/channels/telegram.")}
`;
async function main2(argv) {
  const [command2 = "help", ...rest] = argv;
  switch (command2) {
    case "setup":
      return setup(rest);
    case "status":
      return status();
    case "doctor":
      return doctor();
    case "daemon":
      return daemon(rest);
    case "hook":
      await runHook();
      return 0;
    case "mcp":
      await init_server3().then(() => exports_server);
      await new Promise(() => {
        return;
      });
      return 0;
    case "version":
    case "--version":
    case "-v":
      console.log(VERSION);
      return 0;
    case "help":
    case "--help":
    case "-h":
      console.log(USAGE);
      return 0;
    default:
      console.log(USAGE);
      return 1;
  }
}
process.exit(await main2(process.argv.slice(2)));
